package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    /** The sheet with this id, re-read from the store; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now()));
            } catch (DataIntegrityViolationException e) {
                // Another user created it at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /**
     * The sheet's today. Every feature that decides by the date, or defaults a date, asks this
     * rather than the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return find(id).getToday();
    }

    /** Change the sheet's today; it writes no line of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String user, String id, LocalDate today) {
        Sheet sheet = find(id);
        Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollup.recordChanges(user, id, before);
        return sheet;
    }

    /**
     * Give out the sheet's next claim number. The sheet stays locked until the calling transaction
     * ends, so claims opened at the same moment get different numbers, and a rolled back
     * transaction gives its number back.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.incrementClaimNumber(id) == 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
        return sheets.lastClaimNumber(id);
    }

    /** Whether a claim opened now on the sheet is numbered within its period, not sheet-wide. */
    @Transactional(readOnly = true)
    public boolean numbersByPeriod(String id) {
        return find(id).numbersByPeriod();
    }

    /** Lock the sheet until the calling transaction ends, so changes that must not race take turns. */
    @Transactional
    public void lock(String id) {
        sheets.findLocked(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }

    private Sheet find(String id) {
        return sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}
 * they round half to even. */
function roundsHalfUp(date: string, late: Lateness): boolean {
  return late.policyDate !== null && date < late.policyDate;
}

/** The days in each period an overdue claim gains the late percent for. */
const LATE_PERIOD_DAYS = 30;

/** A settled claim's due is the figure it was settled at (its late charge frozen in); a claim bound by its
 * person's last statement (and not PENDING) has the figure it was bound to; any other has the figure due at the rate `grade`, the
 * one its person has on the claim's date, has now in force on that date, and at least the sheet's floor (n/a
 * when there is no rate). An overdue claim's due adds its late charge to its figure. Live figures round by the
 * date `roundsBy` (see {@link roundsBy}). */
export function claimDue(
  claim: Claim,
  rates: readonly Rate[],
  grade: Grade | undefined,
  floor: string,
  late: Lateness,
  roundsBy: string = claim.date,
): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(roundsBy, late);
  const figure = bound(claim)
    ? (claim.statedDue ?? NO_RATE)
    : correctionFloored(claim, dueOf(claim.amount, grade && rateOn(rates, grade, claim.date), halfUp), floor);
  if (figure === NO_RATE) return figure;
  return sumAmounts([figure, lateCharge(claim, figure, late, halfUp)]);
}

/** A due raised to the sheet's floor, except a correction's, which has no floor. */
function correctionFloored(claim: Claim, due: string, floor: string): string {
  return isCorrection(claim) ? due : floored(due, floor);
}

/** The late charge on an overdue claim: the late percent of its figure for every full 30 days it is overdue,
 * rounded like a due; never bound by a statement, it follows the sheet's today. A correction has none. */
function lateCharge(claim: Claim, figure: string, late: Lateness, halfUp: boolean): string {
  if (isCorrection(claim) || !isOverdue(claim, late.today) || late.today === null) return '0.00';
  const days = (Date.parse(late.today) - Date.parse(claim.dueBy)) / 86_400_000;
  const periods = Math.floor(days / LATE_PERIOD_DAYS);
  return dueOf(figure, timesPct(late.latePct, periods), halfUp);
}

/** A percent with two decimals times a whole number, with two decimals. */
function timesPct(pct: string, times: number): string {
  const [whole, frac = ''] = pct.split('.');
  const hundredths = (BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'))) * BigInt(times);
  return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function isOverdue(claim: Claim, today: string | null): boolean {
  return isOpen(claim) && today !== null && claim.dueBy < today;
